index d773aa5bc717..755a72bec323 100644
--- a/sql/sql_acl.cc
+++ b/sql/sql_acl.cc
@@ -725,7 +725,7 @@ static void acl_insert_user(const char *user, const char *host,
 			    ulong privileges)
 {
   ACL_USER acl_user;
-  acl_user.user=strdup_root(&mem,user);
+  acl_user.user=*user ? strdup_root(&mem,user) : 0;
